-- Gather database schema baseline: the live public schema, generated by
-- scripts/dump-schema.sql. Load into a fresh Supabase project to rebuild
-- the database (no data). Not a migration: do not run it against production.
--
-- Also needed, not part of the schema: the Vault secret ip_hash_salt
-- (same value as IP_HASH_SALT in Vercel), and the edge functions in
-- supabase/functions.

SET check_function_bodies = false;
SET client_min_messages = warning;

-- Extensions
CREATE EXTENSION IF NOT EXISTS pg_stat_statements WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS supabase_vault WITH SCHEMA vault;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS wrappers WITH SCHEMA extensions;

-- Types
DO $t$ BEGIN CREATE TYPE public.user_role AS ENUM ('user', 'admin', 'super_admin'); EXCEPTION WHEN duplicate_object THEN NULL; END $t$;

-- Tables
CREATE TABLE IF NOT EXISTS public.analytics_daily_summary (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    link_id uuid NOT NULL,
    date date NOT NULL,
    clicks integer DEFAULT 0,
    unique_visitors integer DEFAULT 0,
    devices jsonb DEFAULT '{}'::jsonb,
    locations jsonb DEFAULT '{}'::jsonb,
    referrers jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);

