-- Functions
CREATE OR REPLACE FUNCTION public.accept_team_invite(p_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_email text;
  v_invite public.team_invites%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'You need to be signed in to accept an invite' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_invite FROM public.team_invites WHERE token = p_token FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'This invite is invalid or has already been used' USING ERRCODE = 'P0002';
  END IF;

  IF v_invite.expires_at < now() THEN
    RAISE EXCEPTION 'This invite has expired' USING ERRCODE = 'P0001';
  END IF;

  SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
  IF lower(coalesce(v_email, '')) <> lower(v_invite.email) THEN
    RAISE EXCEPTION 'This invite was sent to a different email address' USING ERRCODE = '42501';
  END IF;

  IF v_invite.role NOT IN ('admin', 'editor', 'viewer') THEN
    RAISE EXCEPTION 'Invalid invite role' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.team_members (team_id, user_id, role)
  VALUES (v_invite.team_id, v_uid, v_invite.role)
  ON CONFLICT (team_id, user_id) DO NOTHING;

  DELETE FROM public.team_invites WHERE id = v_invite.id;

  RETURN v_invite.team_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.aggregate_daily_stats(target_date date DEFAULT CURRENT_DATE)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r RECORD;
BEGIN
  FOR r IN 
    SELECT 
      link_id,
      COUNT(*) as total_clicks,
      COUNT(DISTINCT visitor_id) as unique_count,
      jsonb_object_agg(device, count) as device_stats,
      jsonb_object_agg(country, count) as location_stats
    FROM (
      SELECT 
        link_id,
        visitor_id,
        device,
        country,
        COUNT(*) as count
      FROM click_events
      WHERE date(created_at) = target_date
      GROUP BY link_id, visitor_id, device, country
    ) raw_stats
    GROUP BY link_id
  LOOP
    INSERT INTO analytics_daily_summary (
      link_id, date, clicks, unique_visitors, devices, locations
    )
    VALUES (
      r.link_id, target_date, r.total_clicks, r.unique_count, r.device_stats, r.location_stats
    )
    ON CONFLICT (link_id, date) 
    DO UPDATE SET 
      clicks = EXCLUDED.clicks,
      unique_visitors = EXCLUDED.unique_visitors,
      devices = EXCLUDED.devices,
      locations = EXCLUDED.locations,
      updated_at = NOW();
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.claim_guest_link(p_claim_token uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_link_id uuid;
BEGIN
  IF p_user_id IS DISTINCT FROM auth.uid() AND coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501';
  END IF;

  UPDATE public.links
  SET user_id = p_user_id,
      is_guest = false,
      claim_token = NULL,
      expires_at = NULL,
      guest_session_id = NULL,
      metadata = coalesce(metadata, '{}'::jsonb) - 'guest_session_id' - 'guest_email'
  WHERE claim_token = p_claim_token::text
    AND is_guest
  RETURNING id INTO v_link_id;

  IF v_link_id IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired claim token.';
  END IF;

  RETURN jsonb_build_object('success', true, 'link_id', v_link_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_analytics_share_token(p_expires_in_days integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_token TEXT;
    v_expires_at TIMESTAMPTZ;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Sign in to share analytics' USING ERRCODE = '42501';
    END IF;
    -- Generate random token
    v_token := encode(gen_random_bytes(16), 'hex');
    
    -- Calculate expiry if specified
    IF p_expires_in_days IS NOT NULL THEN
        v_expires_at := NOW() + (p_expires_in_days || ' days')::INTERVAL;
    END IF;
    
    -- Insert token
    INSERT INTO analytics_share_tokens (user_id, token, expires_at)
    VALUES (auth.uid(), v_token, v_expires_at);
    
    RETURN v_token;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_guest_link(p_original_url text, p_short_code text, p_guest_session_id text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    new_id uuid := gen_random_uuid();
    token text := gen_random_uuid()::text;
BEGIN
    INSERT INTO public.links (
        id, original_url, short_code, title, clicks, created_at,
        is_guest, guest_session_id, claim_token, metadata
    ) VALUES (
        new_id, p_original_url, p_short_code, 'Guest Link', 0, now(),
        true, p_guest_session_id, token,
        jsonb_build_object('guest_session_id', p_guest_session_id)
    );
    RETURN json_build_object('id', new_id, 'claim_token', token);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_team_invite(p_team_id uuid, p_email text, p_role text, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inviter_id UUID;
  v_invite_id UUID;
  v_count INTEGER;
BEGIN
  v_inviter_id := auth.uid();
  
  -- A. Input Validation
  IF NOT p_email ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' THEN
    RAISE EXCEPTION 'Invalid email address.';
  END IF;

  -- B. Rate Limiting (20 per hour)
  SELECT count(*) INTO v_count FROM team_invites 
  WHERE created_by = v_inviter_id AND created_at > NOW() - INTERVAL '1 hour';
  IF v_count >= 20 THEN
    RAISE EXCEPTION 'Rate limit exceeded: You can only send 20 invites per hour.';
  END IF;

  -- C. Execution
  IF NOT EXISTS (
    SELECT 1 FROM team_members WHERE team_id = p_team_id AND user_id = v_inviter_id AND role IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'Access denied: You must be an owner or admin to invite members.';
  END IF;

  INSERT INTO team_invites (team_id, email, role, token, expires_at, created_by)
  VALUES (p_team_id, p_email, p_role, p_token, NOW() + INTERVAL '7 days', v_inviter_id)
  RETURNING id INTO v_invite_id;

  RETURN jsonb_build_object('id', v_invite_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_team_with_owner(p_name text, p_slug text, p_owner_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_team_id UUID;
  v_count INTEGER;
BEGIN
    IF p_owner_id IS DISTINCT FROM auth.uid() AND coalesce(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501';
    END IF;
  -- A. Input Validation
  IF length(p_name) < 3 OR length(p_name) > 50 THEN
    RAISE EXCEPTION 'Invalid name: Must be between 3 and 50 characters.';
  END IF;
  IF NOT p_slug ~ '^[a-z0-9-]+$' THEN
    RAISE EXCEPTION 'Invalid slug: Must contain only lowercase letters, numbers, and hyphens.';
  END IF;

  -- B. Rate Limiting (5 per hour)
  SELECT count(*) INTO v_count FROM teams 
  WHERE owner_id = p_owner_id AND created_at > NOW() - INTERVAL '1 hour';
  IF v_count >= 5 THEN
    RAISE EXCEPTION 'Rate limit exceeded: You can only create 5 teams per hour.';
  END IF;

  -- C. Execution
  INSERT INTO teams (name, slug, owner_id) VALUES (p_name, p_slug, p_owner_id) RETURNING id INTO v_team_id;
  INSERT INTO team_members (team_id, user_id, role) VALUES (v_team_id, p_owner_id, 'owner');
  RETURN jsonb_build_object('id', v_team_id, 'name', p_name, 'slug', p_slug);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.current_profile_role()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT role::text FROM public.profiles WHERE id = auth.uid();
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_free_link_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tier text;
  v_count integer;
BEGIN
  IF current_user NOT IN ('anon', 'authenticated') THEN
    RETURN NEW;
  END IF;
  IF NEW.user_id IS NULL OR NEW.team_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT subscription_tier INTO v_tier FROM public.profiles WHERE id = NEW.user_id;
  IF coalesce(v_tier, 'free') <> 'free' THEN
    RETURN NEW;
  END IF;

  SELECT count(*) INTO v_count FROM public.links
  WHERE user_id = NEW.user_id AND team_id IS NULL;

  IF v_count >= 15 THEN
    RAISE EXCEPTION 'Link limit reached for Free Tier. Please upgrade to create more links.'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fill_product_url_from_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(NEW.original_url, '') = '' AND NEW.link_id IS NOT NULL THEN
    SELECT original_url INTO NEW.original_url FROM public.links WHERE id = NEW.link_id;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_click_trends(p_user_id uuid, p_days integer DEFAULT 30)
 RETURNS TABLE(day date, click_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        DATE(ce.timestamp) as day,
        COUNT(*)::BIGINT as click_count
    FROM click_events ce
    INNER JOIN links l ON ce.link_id = l.id
    WHERE l.user_id = p_user_id
      AND ce.timestamp > NOW() - (p_days || ' days')::INTERVAL
    GROUP BY DATE(ce.timestamp)
    ORDER BY day ASC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_device_breakdown(p_user_id uuid)
 RETURNS TABLE(device text, browser text, click_count bigint, percentage numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_total BIGINT;
BEGIN
    SELECT COUNT(*) INTO v_total
    FROM click_events ce
    INNER JOIN links l ON ce.link_id = l.id
    WHERE l.user_id = p_user_id;

    RETURN QUERY
    SELECT 
        COALESCE(ce.device, 'Unknown') as device,
        COALESCE(ce.browser, 'Unknown') as browser,
        COUNT(*)::BIGINT as click_count,
        ROUND((COUNT(*)::NUMERIC / NULLIF(v_total, 0)) * 100, 1) as percentage
    FROM click_events ce
    INNER JOIN links l ON ce.link_id = l.id
    WHERE l.user_id = p_user_id
    GROUP BY ce.device, ce.browser
    ORDER BY click_count DESC
