CREATE OR REPLACE FUNCTION public.get_shared_analytics(p_share_token text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_user_id UUID;
    v_display_name TEXT;
    v_result JSON;
BEGIN
    -- Get user_id from token
    SELECT user_id INTO v_user_id
    FROM analytics_share_tokens
    WHERE token = p_share_token
    AND (expires_at IS NULL OR expires_at > NOW());
    
    IF v_user_id IS NULL THEN
        RETURN NULL;
    END IF;
    
    -- Get display name from bio_profiles or profiles
    SELECT COALESCE(bp.display_name, p.full_name, 'User') INTO v_display_name
    FROM profiles p
    LEFT JOIN bio_profiles bp ON bp.user_id = p.id
    WHERE p.id = v_user_id
    LIMIT 1;
    
    -- Build result JSON
    SELECT json_build_object(
        'displayName', v_display_name,
        'stats', (
            SELECT json_build_object(
                'totalClicks', COUNT(*),
                'clicksThisWeek', COUNT(CASE WHEN ce.timestamp >= CURRENT_DATE - INTERVAL '7 days' THEN 1 END),
                'clicksLastWeek', COUNT(CASE WHEN ce.timestamp >= CURRENT_DATE - INTERVAL '14 days' AND ce.timestamp < CURRENT_DATE - INTERVAL '7 days' THEN 1 END),
                'clicksThisMonth', COUNT(CASE WHEN ce.timestamp >= CURRENT_DATE - INTERVAL '30 days' THEN 1 END)
            )
            FROM click_events ce
            INNER JOIN links l ON ce.link_id = l.id
            WHERE l.user_id = v_user_id
        ),
        'countries', (
            SELECT COALESCE(json_agg(c), '[]'::json)
            FROM (
                SELECT country, COUNT(*) as "clickCount"
                FROM click_events ce
                INNER JOIN links l ON ce.link_id = l.id
                WHERE l.user_id = v_user_id AND country IS NOT NULL
                GROUP BY country
                ORDER BY COUNT(*) DESC
                LIMIT 10
            ) c
        ),
        'cities', (
            SELECT COALESCE(json_agg(c), '[]'::json)
            FROM (
                SELECT city, country, COUNT(*) as "clickCount"
                FROM click_events ce
                INNER JOIN links l ON ce.link_id = l.id
                WHERE l.user_id = v_user_id AND city IS NOT NULL
                GROUP BY city, country
                ORDER BY COUNT(*) DESC
                LIMIT 10
            ) c
        ),
        'devices', (
            SELECT COALESCE(json_agg(d), '[]'::json)
            FROM (
                SELECT device, COUNT(*) as "clickCount"
                FROM click_events ce
                INNER JOIN links l ON ce.link_id = l.id
                WHERE l.user_id = v_user_id
                GROUP BY device
                ORDER BY COUNT(*) DESC
                LIMIT 5
            ) d
        ),
        'browsers', (
            SELECT COALESCE(json_agg(b), '[]'::json)
            FROM (
                SELECT COALESCE(browser, 'Unknown') as browser, COUNT(*) as "clickCount"
                FROM click_events ce
                INNER JOIN links l ON ce.link_id = l.id
                WHERE l.user_id = v_user_id
                GROUP BY browser
                ORDER BY COUNT(*) DESC
                LIMIT 5
            ) b
        )
    ) INTO v_result;
    
    RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_top_cities(p_user_id uuid, p_limit integer DEFAULT 10)
 RETURNS TABLE(city text, country text, click_count bigint, percentage numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_total BIGINT;
BEGIN
    -- Get total clicks first
    SELECT COUNT(*) INTO v_total
    FROM click_events ce
    INNER JOIN links l ON ce.link_id = l.id
    WHERE l.user_id = p_user_id AND ce.city IS NOT NULL;

    RETURN QUERY
    SELECT 
        ce.city,
        ce.country,
        COUNT(*)::BIGINT as click_count,
        ROUND((COUNT(*)::NUMERIC / NULLIF(v_total, 0)) * 100, 1) as percentage
    FROM click_events ce
    INNER JOIN links l ON ce.link_id = l.id
    WHERE l.user_id = p_user_id AND ce.city IS NOT NULL
    GROUP BY ce.city, ce.country
    ORDER BY click_count DESC
    LIMIT p_limit;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_traffic_sources(p_user_id uuid)
 RETURNS TABLE(source text, click_count bigint, percentage numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_total BIGINT;
BEGIN
    SELECT COUNT(*) INTO v_total
    FROM click_events ce
    INNER JOIN links l ON ce.link_id = l.id
    WHERE l.user_id = p_user_id;

    RETURN QUERY
    SELECT 
        COALESCE(
            CASE 
                WHEN ce.referrer ILIKE '%google%' THEN 'Google'
                WHEN ce.referrer ILIKE '%facebook%' OR ce.referrer ILIKE '%fb.%' THEN 'Facebook'
                WHEN ce.referrer ILIKE '%twitter%' OR ce.referrer ILIKE '%t.co%' THEN 'Twitter'
                WHEN ce.referrer ILIKE '%instagram%' THEN 'Instagram'
                WHEN ce.referrer ILIKE '%linkedin%' THEN 'LinkedIn'
                WHEN ce.referrer ILIKE '%youtube%' THEN 'YouTube'
                WHEN ce.referrer IS NULL OR ce.referrer = '' THEN 'Direct'
                ELSE 'Other'
            END,
            'Direct'
        ) as source,
        COUNT(*)::BIGINT as click_count,
        ROUND((COUNT(*)::NUMERIC / NULLIF(v_total, 0)) * 100, 1) as percentage
    FROM click_events ce
    INNER JOIN links l ON ce.link_id = l.id
    WHERE l.user_id = p_user_id
    GROUP BY source
    ORDER BY click_count DESC;
END;
$function$
;

