CREATE OR REPLACE FUNCTION public.link_public_json(l public.links)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE WHEN s.gated
    THEN s.base || jsonb_build_object(
      'original_url', '', 'smart_redirects', NULL, 'geo_redirects', NULL,
      'ab_test_config', NULL, 'metadata', '{}'::jsonb)
    ELSE s.base END
  FROM (
    SELECT
      (to_jsonb(l) - 'password_hash' - 'claim_token' - 'guest_session_id' - 'ai_analysis')
        || jsonb_build_object(
             'metadata', coalesce(l.metadata, '{}'::jsonb) - 'guest_email' - 'guest_session_id',
             'requires_password', coalesce(l.password_hash, '') <> '') AS base,
      (coalesce(l.password_hash, '') <> ''
        OR (l.expiration_date IS NOT NULL AND l.expiration_date < now())
        OR (l.start_date IS NOT NULL AND l.start_date > (extract(epoch FROM now()) * 1000)::bigint)
        OR (l.max_clicks IS NOT NULL AND coalesce(l.clicks, 0) >= l.max_clicks)) AS gated
  ) s;
$function$
;

CREATE OR REPLACE FUNCTION public.protect_domain_verification_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_user NOT IN ('anon', 'authenticated') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.domain := lower(trim(NEW.domain));
    IF NEW.status IS DISTINCT FROM 'pending' OR NEW.verified_at IS NOT NULL THEN
      RAISE EXCEPTION 'New domains must start as pending'
        USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status
     OR NEW.verified_at IS DISTINCT FROM OLD.verified_at
     OR NEW.domain IS DISTINCT FROM OLD.domain
     OR NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.verification_token IS DISTINCT FROM OLD.verification_token THEN
    RAISE EXCEPTION 'Domain status and ownership can only be changed by verification'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.protect_profile_privileged_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  billing_cols text[] := ARRAY[
    'subscription_tier',
    'subscription_status',
    'trial_ends_at',
    'razorpay_customer_id',
    'razorpay_subscription_id',
    'stripe_customer_id',
    'stripe_subscription_id'
  ];
  col text;
  new_row jsonb := to_jsonb(NEW);
  old_row jsonb;
  caller_role text;
BEGIN
  IF current_user NOT IN ('anon', 'authenticated') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF coalesce(new_row->>'role', 'user') <> 'user'
       OR coalesce(new_row->>'subscription_tier', 'free') <> 'free'
       OR coalesce(new_row->>'subscription_status', 'active') <> 'active'
       OR new_row->>'trial_ends_at' IS NOT NULL
       OR new_row->>'razorpay_customer_id' IS NOT NULL
       OR new_row->>'razorpay_subscription_id' IS NOT NULL
       OR new_row->>'stripe_customer_id' IS NOT NULL
       OR new_row->>'stripe_subscription_id' IS NOT NULL THEN
      RAISE EXCEPTION 'Not allowed to set billing or role fields on profiles'
        USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  old_row := to_jsonb(OLD);
  caller_role := public.current_profile_role();

  IF (new_row->'role') IS DISTINCT FROM (old_row->'role')
     AND caller_role IS DISTINCT FROM 'super_admin' THEN
    RAISE EXCEPTION 'Only a super admin can change profile roles'
      USING ERRCODE = '42501';
  END IF;

  FOREACH col IN ARRAY billing_cols LOOP
    IF (new_row->col) IS DISTINCT FROM (old_row->col)
       AND coalesce(caller_role, '') NOT IN ('admin', 'super_admin') THEN
      RAISE EXCEPTION 'Not allowed to change %', col
        USING ERRCODE = '42501';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.record_click(p_link_id uuid, p_click_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
    -- Increment click count on links table
    UPDATE links 
    SET clicks = clicks + 1,
        last_clicked = NOW()
    WHERE id = p_link_id;

    -- Insert detailed click event
    INSERT INTO click_events (
        link_id,
        user_agent,
        referrer,
        ip_address,
        country,
        city,
        device,
        browser,
        os,
        utm_source,
        utm_medium,
        utm_campaign,
        utm_term,
        utm_content,
        trigger_source,
        visitor_id,        -- From previous update
        device_model,      -- New field
        destination_url    -- For A/B testing
    ) VALUES (
        p_link_id,
        p_click_data->>'userAgent',
        p_click_data->>'referrer',
        p_click_data->>'ipAddress',
        p_click_data->>'country',
        p_click_data->>'city',
        p_click_data->>'device',
        p_click_data->>'browser',
        p_click_data->>'os',
        p_click_data->>'utm_source',
        p_click_data->>'utm_medium',
        p_click_data->>'utm_campaign',
        p_click_data->>'utm_term',
        p_click_data->>'utm_content',
        p_click_data->>'trigger_source',
        p_click_data->>'visitorId',
        p_click_data->>'deviceModel',     -- Map from input JSON
        p_click_data->>'destinationUrl'
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.strip_raw_ip_address()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  NEW := jsonb_populate_record(NEW, '{"ip_address": null}'::jsonb);
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.unlock_link_checked(p_short_code text, p_password text, p_visitor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  l public.links;
  v text := coalesce(nullif(p_visitor, ''), 'unknown');
BEGIN
  SELECT * INTO l FROM public.links WHERE short_code = p_short_code LIMIT 1;
  IF NOT FOUND OR coalesce(l.password_hash, '') = '' THEN
    RETURN jsonb_build_object('status', 'wrong');
  END IF;

  -- One attempt per link at a time, so parallel guesses can't all pass the
  -- count below before any of their failures is recorded.
  PERFORM pg_advisory_xact_lock(hashtextextended('unlock:' || l.id::text, 0));

  IF (SELECT count(*) FROM public.link_unlock_failures
      WHERE link_id = l.id AND visitor = v AND failed_at > now() - interval '15 minutes') >= 5
     OR (SELECT count(*) FROM public.link_unlock_failures
      WHERE link_id = l.id AND failed_at > now() - interval '1 hour') >= 100 THEN
    RETURN jsonb_build_object('status', 'limited');
  END IF;

  IF p_password IS NULL OR extensions.crypt(p_password, l.password_hash) <> l.password_hash THEN
    INSERT INTO public.link_unlock_failures (link_id, visitor) VALUES (l.id, v);
    DELETE FROM public.link_unlock_failures WHERE link_id = l.id AND failed_at < now() - interval '1 day';
    RETURN jsonb_build_object('status', 'wrong');
  END IF;

  DELETE FROM public.link_unlock_failures WHERE link_id = l.id AND visitor = v;
  l.password_hash := NULL;              -- unlocked: project as unprotected
  RETURN jsonb_build_object('status', 'ok',
    'link', public.link_public_json(l) || jsonb_build_object('requires_password', true));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_guest_link_metadata(p_link_id uuid, p_email text, p_session_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_email IS NULL OR length(p_email) > 254 OR p_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RAISE EXCEPTION 'Invalid email' USING ERRCODE = '22023';
  END IF;
  UPDATE public.links
  SET metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('guest_email', p_email)
  WHERE id = p_link_id
    AND is_guest
    AND guest_session_id IS NOT NULL
    AND guest_session_id = p_session_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_tech_vault_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$
;

-- Views
CREATE OR REPLACE VIEW public.click_stats_by_country WITH (security_invoker=true) AS
 SELECT link_id,
    country,
    country_code,
    count(*) AS click_count,
    count(DISTINCT fingerprint) AS unique_visitors
   FROM public.click_events
  GROUP BY link_id, country, country_code;

CREATE OR REPLACE VIEW public.click_stats_by_city WITH (security_invoker=true) AS
 SELECT link_id,
    country,
    city,
    count(*) AS click_count,
    count(DISTINCT fingerprint) AS unique_visitors
   FROM public.click_events
  GROUP BY link_id, country, city;

CREATE OR REPLACE VIEW public.click_stats_by_device WITH (security_invoker=true) AS
 SELECT link_id,
    device,
    os,
    browser,
    count(*) AS click_count
   FROM public.click_events
  GROUP BY link_id, device, os, browser;

CREATE OR REPLACE VIEW public.click_stats_by_referrer WITH (security_invoker=true) AS
 SELECT link_id,
    referrer,
    count(*) AS click_count
   FROM public.click_events
  GROUP BY link_id, referrer;

CREATE OR REPLACE VIEW public.click_stats_daily WITH (security_invoker=true) AS
 SELECT link_id,
    date("timestamp") AS click_date,
    count(*) AS click_count,
    count(DISTINCT fingerprint) AS unique_visitors
   FROM public.click_events
  GROUP BY link_id, (date("timestamp"))
  ORDER BY (date("timestamp")) DESC;

