-- Policies
CREATE POLICY "Users can view analytics for their own links" ON public.analytics_daily_summary AS PERMISSIVE FOR SELECT TO public
    USING ((EXISTS ( SELECT 1
   FROM public.links
  WHERE ((links.id = analytics_daily_summary.link_id) AND (links.user_id = auth.uid())))));

CREATE POLICY "Owners can revoke their share tokens" ON public.analytics_share_tokens AS PERMISSIVE FOR DELETE TO authenticated
    USING ((user_id = auth.uid()));

CREATE POLICY "Owners can view their share tokens" ON public.analytics_share_tokens AS PERMISSIVE FOR SELECT TO authenticated
    USING ((user_id = auth.uid()));

CREATE POLICY "Users can manage their own API keys" ON public.api_keys AS PERMISSIVE FOR ALL TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Public apps are viewable by everyone" ON public.app_recommendations AS PERMISSIVE FOR SELECT TO public
    USING (true);

CREATE POLICY "Users can delete their own apps" ON public.app_recommendations AS PERMISSIVE FOR DELETE TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Users can insert their own apps" ON public.app_recommendations AS PERMISSIVE FOR INSERT TO public
    WITH CHECK ((auth.uid() = user_id));

CREATE POLICY "Users can update their own apps" ON public.app_recommendations AS PERMISSIVE FOR UPDATE TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Public can view bio profiles" ON public.bio_profiles AS PERMISSIVE FOR SELECT TO public
    USING (true);

CREATE POLICY "Users can create their own bio profiles" ON public.bio_profiles AS PERMISSIVE FOR INSERT TO public
    WITH CHECK ((auth.uid() = user_id));

CREATE POLICY "Users can delete their own bio profiles" ON public.bio_profiles AS PERMISSIVE FOR DELETE TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Users can update their own bio profiles" ON public.bio_profiles AS PERMISSIVE FOR UPDATE TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Users can view their own bio profiles" ON public.bio_profiles AS PERMISSIVE FOR SELECT TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Users can delete own click events" ON public.click_events AS PERMISSIVE FOR DELETE TO public
    USING ((EXISTS ( SELECT 1
   FROM public.links
  WHERE ((links.id = click_events.link_id) AND (links.user_id = auth.uid())))));

CREATE POLICY "Users can view own click events" ON public.click_events AS PERMISSIVE FOR SELECT TO public
    USING ((EXISTS ( SELECT 1
   FROM public.links
  WHERE ((links.id = click_events.link_id) AND (links.user_id = auth.uid())))));

CREATE POLICY "Public can view active domains" ON public.domains AS PERMISSIVE FOR SELECT TO public
    USING ((status = 'active'::text));

CREATE POLICY "Users can create their own domains" ON public.domains AS PERMISSIVE FOR INSERT TO public
    WITH CHECK ((auth.uid() = user_id));

CREATE POLICY "Users can delete their own domains" ON public.domains AS PERMISSIVE FOR DELETE TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Users can update their own domains" ON public.domains AS PERMISSIVE FOR UPDATE TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Users can view their own domains" ON public.domains AS PERMISSIVE FOR SELECT TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Users can delete their own folders" ON public.folders AS PERMISSIVE FOR DELETE TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Users can insert their own folders" ON public.folders AS PERMISSIVE FOR INSERT TO public
    WITH CHECK ((auth.uid() = user_id));

CREATE POLICY "Users can update their own folders" ON public.folders AS PERMISSIVE FOR UPDATE TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Users can view their own folders" ON public.folders AS PERMISSIVE FOR SELECT TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Public Gallery Access" ON public.gallery_items AS PERMISSIVE FOR SELECT TO public
    USING (true);

CREATE POLICY "Public gallery items are viewable by everyone" ON public.gallery_items AS PERMISSIVE FOR SELECT TO public
    USING (true);

CREATE POLICY "Users can delete their own gallery items" ON public.gallery_items AS PERMISSIVE FOR DELETE TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Users can insert their own gallery items" ON public.gallery_items AS PERMISSIVE FOR INSERT TO public
    WITH CHECK ((auth.uid() = user_id));

CREATE POLICY "Users can update their own gallery items" ON public.gallery_items AS PERMISSIVE FOR UPDATE TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Admins can view all links" ON public.links AS PERMISSIVE FOR SELECT TO authenticated
    USING ((public.current_profile_role() = ANY (ARRAY['admin'::text, 'super_admin'::text])));

CREATE POLICY "Team editors can update team links" ON public.links AS PERMISSIVE FOR UPDATE TO authenticated
    USING (((team_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM public.team_members tm
  WHERE ((tm.team_id = links.team_id) AND (tm.user_id = auth.uid()) AND (tm.role = ANY (ARRAY['owner'::text, 'admin'::text, 'editor'::text])))))))
    WITH CHECK (((team_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM public.team_members tm
  WHERE ((tm.team_id = links.team_id) AND (tm.user_id = auth.uid()) AND (tm.role = ANY (ARRAY['owner'::text, 'admin'::text, 'editor'::text])))))));

CREATE POLICY "Team members can view team links" ON public.links AS PERMISSIVE FOR SELECT TO authenticated
    USING (((team_id IS NOT NULL) AND public.is_team_member(team_id)));

CREATE POLICY "Users can delete own links" ON public.links AS PERMISSIVE FOR DELETE TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Users can insert own links" ON public.links AS PERMISSIVE FOR INSERT TO public
    WITH CHECK ((auth.uid() = user_id));

CREATE POLICY "Users can update own links" ON public.links AS PERMISSIVE FOR UPDATE TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Users can view own links" ON public.links AS PERMISSIVE FOR SELECT TO public
    USING ((auth.uid() = user_id));

