CREATE POLICY "Creators can view their subscribers" ON public.newsletter_subscribers AS PERMISSIVE FOR SELECT TO public
    USING ((auth.uid() = user_id));

CREATE POLICY "Public can subscribe to newsletters" ON public.newsletter_subscribers AS PERMISSIVE FOR INSERT TO public
    WITH CHECK (true);

CREATE POLICY "Sellers can view their own orders" ON public.orders AS PERMISSIVE FOR SELECT TO authenticated
    USING ((seller_id = auth.uid()));

CREATE POLICY "Allow public read access" ON public.products AS PERMISSIVE FOR SELECT TO public
    USING (true);

CREATE POLICY "Allow users to manage their own products" ON public.products AS PERMISSIVE FOR ALL TO public
    USING ((auth.uid() = user_id));

