    USING ((auth.uid() = user_id));

CREATE POLICY "Users can insert their own tags" ON public.tags AS PERMISSIVE FOR INSERT TO public
    WITH CHECK ((auth.uid() = user_id));

CREATE POLICY "Users can update their own tags" ON public.tags AS PERMISSIVE FOR UPDATE TO public
    USING ((auth.uid() = user_id));

